function renderProjectList(){
 const all=db.projects.filter(p=>String(p.code||'').trim()&&String(p.name||'').trim());
 const q=(val('projectListSearch')||'').toLowerCase(),stage=val('projectListStage')||'';
 const active=all.filter(p=>!['Completed','On Hold'].includes(p.stage||'Design'));
 const completed=all.filter(p=>(p.stage||'Design')==='Completed');
 const hold=all.filter(p=>(p.stage||'Design')==='On Hold');
 document.getElementById('projectListCards').innerHTML=[
  ['Total Projects',all.length,'#2160e8'],['Ongoing Projects',active.length,'#0a9e55'],['Completed Projects',completed.length,'#22c55e'],['On Hold',hold.length,'#df7b08']
 ].map(([label,n,color])=>`<div class="project-summary-card"><div class="label">${label}</div><div class="value">${n}</div><div class="accent" style="background:${color}"></div></div>`).join('');
 const rows=all.filter(p=>(!stage||(p.stage||'Design')===stage)&&((p.code+' '+p.name).toLowerCase().includes(q)));
 document.getElementById('projectListRows').innerHTML=rows.map((p,i)=>{
  const subs=projectLeafItems(p),tasks=(p.tasks||[]).filter(t=>String(t.name||'').trim());
  const done=subs.filter(x=>x.status==='Completed').length,ip=subs.filter(x=>['In Progress','Under Review'].includes(x.status)).length,open=subs.filter(x=>x.status!=='Completed'&&x.status!=='Cancelled').length,over=subs.filter(x=>x.delay>0).length;
  const progress=subs.length?Math.round(subs.reduce((sum,x)=>sum+(Number(x.progress)||0),0)/subs.length):0;
  const health=(p.stage||'Design')==='Completed'?'Completed':over||subs.some(x=>x.status==='Pending Dependency')?'At Risk':'On Track';
  return `<tr><td>${i+1}</td><td><b>${esc(p.code)}</b></td><td>${esc(p.name)}</td><td>${esc(p.stage||'Design')}</td><td>${fmtDate(p.start)}</td><td>${fmtDate(p.end)}</td><td>${tasks.length}</td><td>${subs.length}</td><td class="dueok">${done}</td><td>${ip}</td><td>${open}</td><td class="${over?'overdue':''}">${over}</td><td><div class="toprow"><div class="dashbar" style="width:100px"><span style="width:${progress}%"></span></div>${progress}%</div></td><td><span class="${health==='At Risk'?'health-risk':'health-good'}">${health}</span></td></tr>`;
 }).join('')||'<tr><td colspan="14">No matching projects.</td></tr>';
}

