  if(p.start&&p.end){let st=new Date(p.start+'T00:00:00'),en=new Date(p.end+'T00:00:00'),span=Math.max(1,(en-st)/86400000),elapsed=Math.max(0,Math.min(span,(todayDate-st)/86400000));planned=p.stage==='Completed'?100:Math.round(elapsed/span*100)}else planned=actual;
