function importBackup(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d||!Array.isArray(d.projects)||!Array.isArray(d.history))throw 0;const ids=new Set();for(const p of d.projects){if(!p||typeof p.id!=='string'||ids.has(p.id)||!Array.isArray(p.tasks||[]))throw 0;ids.add(p.id);for(const t of p.tasks||[])if(!t||typeof t.id!=='string'||!Array.isArray(t.subs||[]))throw 0}
if(!confirm(`Valid backup: ${d.projects.filter(p=>String(p.code||'').trim()).length} project(s), ${d.history.length} date-change record(s).\n\nImporting REPLACES all data currently in this browser. Export a backup of current data first if needed. Continue?`))return;localStorage.setItem(KEY,JSON.stringify(d));load();refreshAll();toast('Backup restored')}catch(err){alert('Invalid backup file. Nothing was changed.')}};r.readAsText(f);e.target.value=''}


const wlCapacityStoreKey='edptWorkloadCapacityV1';let wlSelectedCell=null,wlMonthShift=0,wlExpanded={};
function wlCapacity(person){try{const x=JSON.parse(localStorage.getItem(wlCapacityStoreKey)||'{}');return Number(x[person]||8)}catch(e){return 8}}
function openWorkloadSettings(){document.getElementById('wlSettings').classList.remove('hidden');wlRefreshFilters();}
function saveWorkloadCapacity(){const person=val('wlCapacityPerson'),hours=Number(val('wlCapacityHours'));if(!person||!(hours>0)||hours>24){alert('Select a person and enter capacity between 0 and 24 hours.');return}let x={};try{x=JSON.parse(localStorage.getItem(wlCapacityStoreKey)||'{}')}catch(e){}x[person]=hours;localStorage.setItem(wlCapacityStoreKey,JSON.stringify(x));renderWorkloadPlanner();toast('Daily capacity saved')}
function wlIso(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function wlDateAdd(iso,n){const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+n);return wlIso(d)}
function wlWorking(iso){const day=new Date(iso+'T12:00:00').getDay();return day!==0&&day!==6}
function wlGetRange(){const mode=val('wlRange'),now=new Date(),todayIso=wlIso(now);if(mode==='custom')return [val('wlFrom')||todayIso,val('wlTo')||val('wlFrom')||todayIso];if(mode==='today')return [todayIso,wlDateAdd(todayIso,30)];if(mode==='week'){let d=new Date(now);let offset=(d.getDay()+6)%7;d.setDate(d.getDate()-offset);const a=wlIso(d);return [a,wlDateAdd(a,6)]}let base=new Date(now.getFullYear(),now.getMonth()+wlMonthShift+(mode==='next'?1:0),1,12);if(mode==='next')base=new Date(now.getFullYear(),now.getMonth()+1+wlMonthShift,1,12);if(mode==='month'||mode==='next'){const a=wlIso(base),b=wlIso(new Date(base.getFullYear(),base.getMonth()+1,0,12));return [a,b]}return [todayIso,wlDateAdd(todayIso,30)]}
function workloadRangeChanged(){document.getElementById('wlCustomRange').classList.toggle('hidden',val('wlRange')!=='custom');wlMonthShift=0;renderWorkloadPlanner()}
function shiftWorkload(n){wlMonthShift+=n;const mode=val('wlRange');if(mode==='custom'){let a=val('wlFrom');if(a)document.getElementById('wlFrom').value=wlDateAdd(a,n*30);let b=val('wlTo');if(b)document.getElementById('wlTo').value=wlDateAdd(b,n*30)}renderWorkloadPlanner()}
function wlFlatten(){const out=[];(db.projects||[]).forEach(p=>(p.tasks||[]).forEach(t=>{const activeSubs=(t.subs||[]).filter(s=>!['Cancelled','Completed'].includes(s.status)&&String(s.name||'').trim());if(activeSubs.length){activeSubs.forEach(s=>{const owner=String(s.owner||t.owner||'').trim(),start=s.start||t.start||p.start,end=s.target||t.target||p.end,entered=Number(s.plannedHours||s.estimatedHours||0);if(!owner||!start||!end||start>end)return;const hours=entered>0?entered:wlWorkingDaysBetween(start,end)*wlCapacity(owner);out.push({p,t,item:s,owner,start,end,hours,status:s.status||t.status||'Not Started',priority:s.priority||t.priority||'',tags:s.tags||t.tags||[],hoursEstimated:entered>0})})}else{const owner=String(t.owner||'').trim(),start=t.start||p.start,end=t.target||p.end,entered=Number(t.plannedHours||t.estimatedHours||0);if(owner&&start&&end&&start<=end&&!['Completed','Cancelled'].includes(t.status)){const hours=entered>0?entered:wlWorkingDaysBetween(start,end)*wlCapacity(owner);out.push({p,t,item:t,owner,start,end,hours,status:t.status||'Not Started',priority:t.priority||'',tags:t.tags||[],hoursEstimated:entered>0})}}}));return out}
function wlWorkingDaysBetween(start,end){let count=0,d=start,guard=0;while(d&&d<=end&&guard++<800){if(wlWorking(d))count++;d=wlDateAdd(d,1)}return count}
function wlAllocate(items,from,to){const allocations=[];items.forEach(x=>{let days=[],d=x.start,guard=0;while(d&&d<=x.end&&guard++<800){if(wlWorking(d))days.push(d);d=wlDateAdd(d,1)}if(!days.length)return;const daily=x.hoursEstimated?x.hours/days.length:wlCapacity(x.owner);let remaining=x.hours;days.forEach((date,i)=>{if(remaining<=0)return;const hours=i===days.length-1?remaining:Math.min(daily,remaining);if(hours>0){allocations.push({...x,date,hours});remaining-=hours}})});return allocations.filter(a=>a.date>=from&&a.date<=to)}
function wlRefreshFilters(){const allItems=wlFlatten();const tags=[...new Set(allItems.flatMap(x=>Array.isArray(x.tags)?x.tags:String(x.tags||'').split(',')).map(t=>String(t).trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b));const tagEl=document.getElementById('wlTag');if(tagEl){const oldTag=tagEl.value;tagEl.innerHTML='<option value="">All tags</option>'+tags.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');if(tags.includes(oldTag))tagEl.value=oldTag;}const people=[...new Set(allItems.map(x=>x.owner))].sort((a,b)=>a.localeCompare(b));const ass=document.getElementById('wlAssignee'),old=ass.value;ass.innerHTML='<option value="">All assignees</option>'+people.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');if(people.includes(old))ass.value=old;const cap=document.getElementById('wlCapacityPerson'),oldc=cap.value;cap.innerHTML=people.map(n=>`<option value="${esc(n)}">${esc(n)}</option>`).join('');if(people.includes(oldc))cap.value=oldc;const pr=document.getElementById('wlProject'),selected=[...pr.selectedOptions].map(o=>o.value);pr.innerHTML=db.projects.filter(p=>String(p.code||'').trim()).map(p=>`<option value="${esc(p.id)}">${esc(p.code+' — '+p.name)}</option>`).join('');[...pr.options].forEach(o=>o.selected=selected.includes(o.value))}
function renderWorkloadPlanner(){const body=document.getElementById('wlBody');if(!body)return;wlRefreshFilters();const [from,to]=wlGetRange();if(from>to){body.innerHTML='<tr><td>From Date must be on or before To Date.</td></tr>';return}const projectIds=[...document.getElementById('wlProject').selectedOptions].map(o=>o.value),assignee=val('wlAssignee'),tag=val('wlTag'),q=(val('wlSearch')||'').toLowerCase();let items=wlFlatten().filter(x=>(!projectIds.length||projectIds.includes(x.p.id))&&(!assignee||x.owner===assignee)&&(!tag||(Array.isArray(x.tags)?x.tags:String(x.tags||'').split(',')).map(t=>String(t).trim()).includes(tag))&&`${x.owner} ${x.p.code} ${x.p.name} ${x.t.name} ${x.item.name}`.toLowerCase().includes(q));const alloc=wlAllocate(items,from,to);let dates=[],d=from,guard=0;while(d<=to&&guard++<100){dates.push(d);d=wlDateAdd(d,1)}const people=[...new Set(alloc.map(a=>a.owner))].sort((a,b)=>a.localeCompare(b));document.getElementById('wlPeriodLabel').textContent=fmtDate(from)+' – '+fmtDate(to);const monthGroups=[];dates.forEach(date=>{const m=date.slice(0,7);let g=monthGroups.find(x=>x.m===m);if(!g){g={m,count:0};monthGroups.push(g)}g.count++});const weekGroups=[];dates.forEach(date=>{const dt=new Date(date+'T12:00:00'),monday=new Date(dt);monday.setDate(dt.getDate()-((dt.getDay()+6)%7));const key=wlIso(monday);let g=weekGroups.find(x=>x.key===key);if(!g){g={key,count:0};weekGroups.push(g)}g.count++});document.getElementById('wlHead').innerHTML='<tr><th class="wl-person wl-month" rowspan="3">NAME</th>'+monthGroups.map(g=>`<th class="wl-month" colspan="${g.count}">${new Date(g.m+'-15T12:00:00').toLocaleDateString('en-GB',{month:'short',year:'numeric'}).toUpperCase()}</th>`).join('')+'<th class="wl-total" rowspan="3">TOTAL<br>HOURS</th></tr><tr><th class="wl-week" colspan="'+dates.length+'" style="display:none"></th>'+weekGroups.map(g=>`<th class="wl-week" colspan="${g.count}">${new Date(g.key+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}).toUpperCase()}</th>`).join('')+'</tr><tr>'+dates.map(date=>`<th class="wl-datehead ${!wlWorking(date)?'wl-grey':''}" title="${fmtDate(date)}">${date.slice(8,10)}<small>${new Date(date+'T12:00:00').toLocaleDateString('en-GB',{weekday:'short'}).slice(0,1)}</small></th>`).join('')+'</tr>';
const perDay=(person,date)=>alloc.filter(a=>a.owner===person&&a.date===date).reduce((sum,a)=>sum+a.hours,0);document.getElementById('wlBody').innerHTML=people.map(person=>{const total=alloc.filter(a=>a.owner===person).reduce((s,a)=>s+a.hours,0);return `<tr><th class="wl-person"><button class="wl-expand" onclick="wlExpanded['${esc(person)}']=!wlExpanded['${esc(person)}'];renderWorkloadPlanner()">${wlExpanded[person]?'▾':'▸'}</button> ${esc(person)}<small>${new Set(alloc.filter(a=>a.owner===person).map(a=>a.p.code)).size} project(s)</small></th>`+dates.map(date=>{const h=perDay(person,date),cap=wlCapacity(person),cls=!wlWorking(date)?'wl-grey':h>cap?'wl-red':h>0?'wl-green':'wl-white';return `<td class="wl-cell ${cls}" title="${fmtDate(date)} · ${h.toFixed(1)}h / ${cap}h capacity" onclick="showWorkloadCell('${esc(person)}','${date}')">${h?Number(h.toFixed(2))+'h':'—'}</td>`}).join('')+`<td class="wl-total">${total.toFixed(1)}h</td></tr>`+(wlExpanded[person]?alloc.filter(a=>a.owner===person).reduce((arr,a)=>{if(!arr.some(y=>y.key===a.p.id+'|'+a.t.id+'|'+a.item.id))arr.push({...a,key:a.p.id+'|'+a.t.id+'|'+a.item.id});return arr},[]).map(a=>`<tr><td class="wl-person">↳ ${esc(a.p.code)} · ${esc(a.t.name)} / ${esc(a.item.name||a.t.name)}<small>${fmtDate(a.start)}–${fmtDate(a.end)}</small></td>`+dates.map(date=>{const h=alloc.filter(y=>y.owner===person&&y.date===date&&y.p.id===a.p.id&&y.t.id===a.t.id&&y.item.id===a.item.id).reduce((s,y)=>s+y.hours,0);return `<td class="${h>wlCapacity(person)?'wl-red':h?'wl-green':'wl-white'}">${h?h.toFixed(1)+'h':'—'}</td>`}).join('')+`<td class="wl-total">${a.hours.toFixed(1)}h*</td></tr>`).join(''):'')}).join('')||`<tr><td colspan="${dates.length+2}">No assigned tasks with an owner, dates and estimated hours in this range. Enter estimated hours and dates in Task Management to populate this calendar.</td></tr>`;
const capDays=dates.filter(wlWorking).length,summary=people.map(person=>{const aa=alloc.filter(a=>a.owner===person),hrs=aa.reduce((s,a)=>s+a.hours,0),booked=new Set(aa.map(a=>a.date)).size,over=new Set(aa.filter(a=>perDay(person,a.date)>wlCapacity(person)).map(a=>a.date)).size,projects=[...new Set(aa.map(a=>a.p.code+' — '+a.p.name))];return `<tr><td>${esc(person)}</td><td>${projects.map(esc).join('<br>')}</td><td>${booked} / ${capDays}</td><td>${hrs.toFixed(1)}</td><td>${(capDays*wlCapacity(person)).toFixed(1)}</td><td class="${over?'overdue':''}">${over}</td><td>${Math.max(0,capDays*wlCapacity(person)-hrs).toFixed(1)}h</td></tr>`}).join('');document.getElementById('wlSummary').innerHTML=summary||'<tr><td colspan="7">No workload in selected range.</td></tr>';}
function showWorkloadCell(person,date){const [from,to]=wlGetRange(),projectIds=[...document.getElementById('wlProject').selectedOptions].map(o=>o.value),q=(val('wlSearch')||'').toLowerCase();const items=wlFlatten().filter(x=>x.owner===person&&(!projectIds.length||projectIds.includes(x.p.id))&&`${x.owner} ${x.p.code} ${x.p.name} ${x.t.name} ${x.item.name}`.toLowerCase().includes(q));const aa=wlAllocate(items,date,date),total=aa.reduce((s,a)=>s+a.hours,0),cap=wlCapacity(person);document.getElementById('wlPopupIntro').textContent=`${person} · ${fmtDate(date)} · Allocated ${total.toFixed(1)}h · Capacity ${cap}h · Overload ${Math.max(0,total-cap).toFixed(1)}h`;document.getElementById('wlBreakdown').innerHTML=aa.map(a=>`<tr><td>${esc(a.p.code)}</td><td>${esc(a.p.name)}</td><td>${esc(a.t.name)} / ${esc(a.item.name||a.t.name)}</td><td>${a.hours.toFixed(1)}h</td><td>${Number(a.item.plannedHours||a.item.estimatedHours||a.t.plannedHours||a.t.estimatedHours||0).toFixed(1)}h${a.hoursEstimated?'':' (timeline-based)'}</td><td>${esc(a.status)}</td><td>${esc(a.priority||'—')}</td><td>${fmtDate(a.start)}</td><td>${fmtDate(a.end)}</td><td><button class="small" onclick="openWorkloadTask('${a.p.id}','${a.t.id}')">Open task</button></td></tr>`).join('')||'<tr><td colspan="10">No workload for this person on this date. Add or update a task in Task Management.</td></tr>';wlSelectedCell={person,date};}
