/* ===== v7: settings, themes, final workload layout ===== */
const WSD={theme:'dark',accent:'#3ecf8e',uiv:2,ulMode:'acc',cg:'#1f9d3a',co:'#d92d43',ch:'#d99a00',cw:'#8a97ab',limit:8,range:'today',colw:'normal',rowh:'normal',fs:'14',weekends:true};
