items.forEach(x=>{(P[x.owner]??={n:x.owner,days:{}});const m=wxAlloc(x,hol);dates.forEach(d=>{if(m[d])P[x.owner].days[d]=(P[x.owner].days[d]||0)+m[d]})});
wxUnpl(P,dates);wxTeam().filter(n=>(!val('wlAssignee')||n===val('wlAssignee'))&&wxPplOK(n)).forEach(n=>P[n]??={n,days:{}});
const cls=d=>hm[d]?'wl-hol':we(d)?'wl-we':'';
let h='<thead><tr><th class="wl-nm">Name</th>'+dates.map(d=>`<th class="${cls(d)}" title="${esc(fmtDate(d)+(hm[d]?' – '+hm[d]:''))}"><span>${'SMTWTFS'[dow(d)]}</span><b>${+d.slice(8)}</b></th>`).join('')+'<th class="wl-tt">Total</th></tr></thead>';
let body='';Object.values(P).sort((a,b)=>a.n.localeCompare(b.n)).forEach(r=>{const tot=dates.reduce((s,d)=>s+(r.days[d]||0),0);
body+=`<tr><td class="wl-nm ${tot?'':'wl-idle'}">${esc(r.n)}</td>`+dates.map(d=>{const v=r.days[d]||0,c=hm[d]?'wl-hol':we(d)?'wl-we':v>cap+0.005?'wl-o':v>0?'wl-g':'';return `<td class="${c}${v&&!hm[d]?' wl-click':''}" data-n="${esc(r.n)}" data-d="${d}" title="${v?'Open in Task Management':esc(hm[d]||'')}">${v&&!hm[d]?+v.toFixed(2):''}</td>`}).join('')+`<td class="wl-tt">${tot.toFixed(2)}</td></tr>`});
const g=document.getElementById('wlGrid');g.innerHTML=h+`<tbody>${body||`<tr><td colspan="${dates.length+2}" style="text-align:left;padding:16px">No hours to show. In Task Management enter an owner, dates and Estimated Hours for an activity.</td></tr>`}</tbody>`;
g.onclick=e=>{const c=e.target.closest('td.wl-click');if(c)wxOpen(c.dataset.n,c.dataset.d)};
