const twK = (() => { const k = []; let n = 2; while (k.length < 64) { let p = true; for (let i = 2; i * i <= n; i++) if (n % i === 0) { p = false; break } if (p) k.push(Math.floor((Math.cbrt(n) % 1) * 4294967296) | 0); n++ } return k })();
