 document.getElementById('twPfOut').onclick = twLogout;
 document.getElementById('twPf').onsubmit = e => { e.preventDefault(); const er = twPwSave(document.getElementById('twPf'), true); if (er) document.getElementById('twPerr').textContent = er; else { toast('Password saved'); twEnter() } }
