const twPwFields = forced => `${forced ? '' : '<div class="tw-f"><label for="twPw0">Current password</label><input id="twPw0" type="password" autocomplete="current-password" required></div>'}<div class="tw-f"><label for="twPw1">New password (at least 8 characters)</label><input id="twPw1" type="password" autocomplete="new-password" minlength="8" required></div><div class="tw-f"><label for="twPw2">Confirm new password</label><input id="twPw2" type="password" autocomplete="new-password" minlength="8" required></div>`;
