/* ---------- modal ---------- */
function twModal(title, body, onSave, saveLabel = 'Save', wide) {
 const m = document.createElement('div'); m.className = 'tw-modal';
 m.innerHTML = `<form class="tw-dlg" ${wide ? 'style="width:min(880px,100%)"' : ''}><h3>${title}</h3>${body}<div class="tw-err" data-err></div><div class="tw-foot"><button type="button" data-x>${onSave ? 'Cancel' : 'Close'}</button>${onSave ? `<button class="primary" type="submit">${saveLabel}</button>` : ''}</div></form>`;
 document.body.appendChild(m);
 m.querySelector('[data-x]').onclick = () => m.remove(); m.onclick = e => { if (e.target === m) m.remove() };
 m.querySelector('form').onsubmit = e => { e.preventDefault(); if (!onSave) return m.remove(); const er = onSave(m); if (er) m.querySelector('[data-err]').textContent = er; else m.remove() };
 setTimeout(() => m.querySelector('textarea,input,select')?.focus(), 0);
 return m
}

