twGuard(['importTaskTemplate'], () => twTaskCan('Add'), twTaskNoPerm);
twGuard(['editSubtask', 'openLinkPicker', 'lkSave'], () => twTaskCan('Edit'), twTaskNoPerm);
twGuard(['lkShiftPrompt', 'lkShiftTask'], () => twTaskCan('Edit') || twTaskCan('Update'), twTaskNoPerm);
