twGuard(['wxShiftPick', 'wxAddHol', 'wxDelHol', 'wxSettings', 'addIssue', 'setIssueStatus', 'delIssue', 'wsSet', 'wsReset'], twAdmin, twNoPerm);
twGuard(['saveManualHighlights'], () => twLead(twU()), 'Only Team Leaders, Managers and the admin can update the Project Review.');
const TW_OWNER_FIELDS = ['status', 'pct', 'actualHours', 'dependency'];
