(function(){const nat=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');
const fmt=v=>/^\d{4}-\d{2}-\d{2}$/.test(v)?v.slice(8)+'/'+v.slice(5,7)+'/'+v.slice(0,4):'';
function enh(el){if(el.dataset.dp||!el.parentNode)return;el.dataset.dp='1';const w=document.createElement('span');w.className='dp';el.parentNode.insertBefore(w,el);w.appendChild(el);const lab=document.createElement('span');lab.className='dp-l';w.appendChild(lab);
const upd=()=>{const t=fmt(nat.get.call(el));lab.textContent=t||'DD/MM/YYYY';lab.classList.toggle('ph',!t)};
Object.defineProperty(el,'value',{get(){return nat.get.call(this)},set(v){nat.set.call(this,v);upd()},configurable:true});
el.addEventListener('input',upd);el.addEventListener('change',upd);el.addEventListener('click',()=>{try{el.showPicker()}catch(e){}});upd()}
const run=r=>r.querySelectorAll&&r.querySelectorAll('input[type=date]:not([data-dp])').forEach(enh);
new MutationObserver(ms=>ms.forEach(m=>m.addedNodes.forEach(n=>{if(n.nodeType!==1)return;if(n.matches&&n.matches('input[type=date]'))enh(n);else run(n)}))).observe(document.body,{childList:true,subtree:true});run(document)})();
