/* ---- automatic link scheduling: a linked task starts the working day after the task it follows ---- */
function lkSnapSub(p,r,log){const o=r.o;if(['Completed','Cancelled'].includes(o.status))return false;const m=lkMaxPred(p,o);if(!m)return false;const want=lkNext(m);if(o.start===want)return false;const oS=o.start,oT=o.target;
if(!oS&&!oT){log.push({r,f:'start',old:'',nv:want});o.start=want;return true}
const n=(oS&&oT&&oS<=oT)?wdCount(oS,oT):1;log.push({r,f:'start',old:oS||'',nv:want});o.start=want;if(oT){const nt=wdStep(want,Math.max(n-1,0));log.push({r,f:'target',old:oT,nv:nt});o.target=nt}return true}
function lkSnapMain(p,r,log,q){const o=r.o,m=lkMaxPred(p,o);if(!m)return false;const want=lkNext(m),cur=o.start;if(!cur||cur===want)return false;const d=wdDiff(cur,want);if(!d)return false;
(o.subs||[]).forEach(sb=>{const rr={id:sb.id,o:sb,main:o,name:o.name+' / '+sb.name};lkShiftRec(rr,d,log);q.push(sb.id)});lkRoll(p);return true}
function lkSnapChain(p,ids,reason,self,before){before=before||lkTargets(p);const log=[],mainsDone=new Set();
const run=start=>{const q=[...start];let g=0;while(q.length&&g++<6000){const id=q.shift(),recs=lkRecs(p);recs.filter(r=>(r.o.links||[]).includes(id)).forEach(s=>{const ch=s.main?lkSnapSub(p,s,log):lkSnapMain(p,s,log,q);if(ch)q.push(s.id)})}};
if(self)ids.forEach(id=>{const r=lkRecs(p).find(x=>x.id===id);if(r){const q=[];const ch=r.main?lkSnapSub(p,r,log):lkSnapMain(p,r,log,q);if(ch)run([id,...q])}});
run(ids);lkRoll(p);
p.tasks.forEach(m=>{const b=before[m.id];if(b&&m.target&&b!==m.target&&!mainsDone.has(m.id)){mainsDone.add(m.id);run([m.id])}});lkRoll(p);
if(log.length){lkLog(p,log,reason);toast(new Set(log.map(l=>l.r.id)).size+' linked task(s) rescheduled automatically')}return log}
function lkAfter(p,rootId,n,before,reason){lkSnapChain(p,[rootId],reason||'Linked task moved',false,before);lkFinish(p)}
function lkSave(){const {pid,id}=window._lk,p=pbyid(pid),rec=lkRecs(p).find(r=>r.id===id),ids=[...document.querySelectorAll('#lkList input:checked')].map(i=>i.value);rec.o.links=ids;lkClose();lkSnapChain(p,[id],'Scheduled after linked task',true);lkFinish(p);toast('Links saved')}
