function ulOpen(){if(!twU())return;db.unplanned=db.unplanned||[];const ps=db.projects.filter(p=>String(p.code||'').trim()),me=twU().owner||twU().name;
twModal('Log Unplanned Work',`<p class="muted" style="margin:0">Work that came in on top of the plan. The hours use up that person's day and the person's open tasks are re-planned automatically.</p><div class="tw-2"><div class="tw-f"><label for="ulP">Person</label><select id="ulP">${ulNames().map(n=>`<option ${n===me?'selected':''}>${esc(n)}</option>`).join('')}</select></div><div class="tw-f"><label for="ulD">Date</label><input id="ulD" type="date" value="${twToday()}" required></div>
<div class="tw-f"><label for="ulH">Hours</label><input id="ulH" type="number" min="0.25" max="24" step="0.25" value="4" required></div><div class="tw-f"><label for="ulPr">Project (optional)</label><select id="ulPr"><option value="">—</option>${ps.map(p=>`<option value="${esc(p.id)}">${esc(p.code)}</option>`).join('')}</select></div></div><div class="tw-f"><label for="ulN">What was it?</label><input id="ulN" required maxlength="160" placeholder="e.g. Urgent customer drawing change"></div>`,m=>{
const h=Number(m.querySelector('#ulH').value),d=m.querySelector('#ulD').value,n=m.querySelector('#ulN').value.trim(),pe=m.querySelector('#ulP').value;if(!(h>=0.25&&h<=24))return 'Hours must be between 0.25 and 24.';if(!d)return 'Pick the date.';if(!n)return 'Describe the unplanned work.';
const e={id:uid(),person:pe,date:d,hours:h,projectId:m.querySelector('#ulPr').value,note:n,by:TW.me,at:Date.now()};db.unplanned.push(e);const r=ulApply(e);save(false);refreshTaskViews();toast(r)},'Log & re-plan')}
function ulApply(e){const cap=wlCapacity(),hol=wxHol(),D=e.date,key=e.person.toLowerCase();db.slip=db.slip||{};
let load=0;wxItems().filter(x=>x.owner.toLowerCase()===key&&!['Completed','Cancelled'].includes(x.status)).forEach(x=>{load+=(wxAlloc(x,hol)[D]||0)});(db.unplanned||[]).filter(u=>u.person.toLowerCase()===key&&u.date===D&&u.id!==e.id).forEach(u=>load+=Number(u.hours));
const work=wxWork(D,hol),lost=work?Math.max(e.hours-Math.max(cap-load,0),0):0;let bank=(db.slip[key]||0)+lost,days=0;
if(lost>0){if(WS.ulMode==='up'){days=Math.ceil(bank/cap);bank=0}else{days=Math.floor(bank/cap);bank-=days*cap}}
db.slip[key]=+bank.toFixed(2);e.lost=+lost.toFixed(2);e.shift=days;let moved=0;
if(days>0){const why=`Unplanned work: ${e.note} (${e.hours} h on ${fmtDate(D)})`;db.projects.forEach(p=>{const ch=[],log=[];p.tasks.forEach(t=>(t.subs||[]).forEach(s=>{if(String(s.owner||'').toLowerCase()!==key||['Completed','Cancelled'].includes(s.status)||!s.target||s.target<D)return;const r={id:s.id,o:s,main:t,name:t.name+' / '+s.name};if(s.start&&s.start<=D)['target'].forEach(f=>{const nv=wdStep(s[f],days);log.push({r,f,old:s[f],nv});s[f]=nv});else lkShiftRec(r,days,log);ch.push(s.id);moved++}));
if(ch.length){lkLog(p,log,why);const before=lkTargets(p);lkRoll(p);lkSnapChain(p,ch,why,false,before)}})}
const nm=e.person;return lost>0?`${e.hours} h logged for ${nm}. ${days>0?`Open tasks moved ${days} working day(s) later (${moved} subtask(s)).`:`Schedule slip so far: ${db.slip[key]} h — dates move at ${cap} h.`}`:`${e.hours} h logged for ${nm}. Absorbed by free time — no date change.`}
